-- Generated by scripts/build-bob-phase-tools-catalog.ts from scripts/data/tool-cards.json.
-- Owner decision 2026-10-29: six permanent tools plus four by project phase
-- (design while drawing work is pending), loaded in full from the first step,
-- and cards that say when to use each other tool and what it gives.
-- Install both matching Edge runtimes before activation. Existing manifests remain pinned.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $phase_tools_publication$
declare specs jsonb:=$phase_tools_spec$[{"key":"bob.tools","core_tools_before":["describe_tool","open_project_item","read_solution_context","read_construction_draft","change_construction_parameters"],"core_tools":["describe_tool","search_project_data","open_project_item","list_project_category","read_solution_context","read_work_context"],"phase_tools":{"concept":["create_solution_alternative","select_solution_alternative","read_construction_draft","save_construction_draft"],"design":["read_construction_draft","check_construction_draft","change_construction_parameters","design_project_cad"],"planning":["search_material_catalog","derive_construction_lists","edit_work_record","calculate_project"],"build":["edit_work_record","change_work_state","read_drawing_requests","calculate_project"],"complete":["edit_work_record","change_work_state","read_drawing_requests","search_conversation_history"]}},{"key":"tools.archive_project_area","card_before":"Archive an Area that is finished or no longer used, or restore an archived Area.","card":"Use when an Area is finished or no longer used and should leave active planning, or an archived Area should return. Gives the archived or restored Area with its history and completed work kept; unfinished Tasks must be moved or finished first."},{"key":"tools.archive_project_measurement","card_before":"Archive or restore an existing project measurement.","card":"Use when a measurement is obsolete and should leave active use without a replacement, or an archived one should return. Gives the archived or restored revision with history kept; drawings that depend on it then show stale evidence."},{"key":"tools.attach_project_image","card_before":"Attach an existing image to the relevant project work.","card":"Use when an image already in the project library should appear on an Area, Task, Task instruction step or plan Step. Gives the new attachment, reusing the original file without uploading again."},{"key":"tools.audit_project_plan","card_before":"Audit the current approved living plan against authorised project evidence with the read-only mini compiler and nano reviewer.","card":"Use when you want to know whether the current approved living plan still matches the project's evidence. Gives a read-only review of representation and evidence problems in that plan; it takes no arguments and changes nothing."},{"key":"tools.calculate_project","card_before":"Execute traceable versioned calculations in code.","card":"Use when a number must be computed in code rather than by you: a parameter graph, a stair on a plan, replay of a saved Construction, stair or material purchase, or supplier pack quotes. Gives values with units, rounding, provenance and source readiness; read-only."},{"key":"tools.cancel_drawing_request","card_before":"Cancel the initiating member's drawing request and fence late saves.","card":"Use when the owner asks to stop their own drawing request. Gives the cancelled request, so late renders can no longer be saved; drawings already saved stay as they are."},{"key":"tools.change_building_scope","card_before":"Link a building, mark its rooms and map Areas for this project.","card":"Use when the owner has identified the building or rooms this project covers. Gives the linked or unlinked building, marked rooms or mapped Areas, with fresh refs; linking a whole building shares its rooms, notes and measurements with every member."},{"key":"tools.change_construction_parameters","card_before":"Change saved construction input nodes; server recomputes dependencies and retains exact version history.","card":"Use when only values of existing input parameters change in a saved Construction, such as a width, or a newer revision of the same measurement. Gives a new revision with dependent dimensions recomputed and its check; parts, formulas, materials and joints stay. Can update the selected Solution atomically."},{"key":"tools.change_construction_roles","card_before":"Classify saved part-instance roles without reconstructing geometry.","card":"Use when saved part instances should be classified as built, existing, prefabricated or reference only. Gives a new Construction revision with those roles and its geometry unchanged; read_construction_changes then shows affected outputs."},{"key":"tools.change_plan_focus","card_before":"Choose or clear Bob focus using a saved read.","card":"Use when you shift which plan Step you are concentrating on, or clear that focus. Gives the new Bob focus; Step states, Tasks and parallel work stay unchanged."},{"key":"tools.change_plan_task_link","card_before":"Organise existing Tasks through server-bound plan links.","card":"Use when an existing Task should be tied to a plan Step: assign an unowned Task, add a reference, move its primary Step, or unlink. Gives the changed association with the Task's content, status, people and other links kept; it creates no Tasks."},{"key":"tools.change_solution_evidence","card_before":"Change one source link while preserving other solution data","card":"Use when a Solution's evidence links change: add or remove a measurement, set or clear its primary image, or add or remove a design reference image. Gives the Solution with only that link changed and all other content kept."},{"key":"tools.change_task_readiness","card_before":"Change one Task dependency or need from its exact read context.","card":"Use when a Task gains, loses or changes a dependency or a tool or information need, a need becomes ready from evidence, or readiness is confirmed. Gives the Task's updated needs and dependencies, or the specific blocker when refused."},{"key":"tools.change_work_relation","card_before":"Add or remove one assignment or scheduled Task.","card":"Use when one person should be assigned to or removed from a Task, or one Task added to or removed from a build day. Gives the changed relation with all other members kept; RSVP, readiness and completion are untouched."},{"key":"tools.change_work_state","card_before":"Change lifecycle or Task status on an exact read record.","card":"Use when a work record's state changes: archive or restore an Area or measurement, delete an unfinished Task, build day or Shopping row, set a Task status, or move the project or an Area to another phase. Gives the changed state with all other data kept."},{"key":"tools.check_construction_cut_fit","card_before":"Check rectangular blank placement against explicit candidate sheets with kerf, trim and grain.","card":"Use when you need to know whether all rectangular blanks of the current checked Construction fit on candidate sheet formats you specify, with kerf, trim and grain. Gives a read-only cutting layout with placements, cut order and offcuts, or a concrete gap; save_construction_cut_plan keeps one."},{"key":"tools.check_construction_draft","card_before":"Check an exact saved construction for supported geometry, material dimensions and joint consistency.","card":"Use when a saved Construction needs a check its save did not already return: a local part scope, feature requirement probes, or its saved drawings, requirements and cut plans. Gives bounded findings for that exact revision (collisions, faces, joints, material mismatches) and concept_ready."},{"key":"tools.compile_project_plan","card_before":"Compile Bob's plan intent into exact Steps/Requirements and return nano's advisory review to Bob. Read-only; Bob decides corrections and saving.","card":"Use when the project needs its first living plan or a broad replan from your plan intent. Gives a read-only compilation into Steps and Completion Requirements plus an advisory review, ready for save_compiled_project_plan; focused changes go through edit_project_plan."},{"key":"tools.compose_cad_shell","card_before":"Combine separately saved CAD pieces into one shell drawing, and move, add, remove or update pieces in it.","card":"Use when separately saved CAD drawings such as rooms, walls and furniture should stand together in one shell drawing, or a shell piece should be moved, added, removed or re-pinned to its newer revision. Gives the shell's new revision; pieces are placed by reference, never redrawn."},{"key":"tools.continue_construction_change","card_before":"Recalculate one saved affected output from canonical inputs.","card":"Use when one affected-output item from read_construction_changes should be carried forward. Gives that same output recalculated through its normal writer, the drawing pins to render, or a recorded Step work review; one item per call."},{"key":"tools.create_project_room_layout","card_before":"Create the existing two-rectangular-room layout with one shared wall and one linked storage-box drawing. Not a general house or furniture layout.","card":"Use when the owner wants a 2D plan of two existing rooms on one level sharing one wall, with one existing storage-box drawing placed in it. Gives a new linked plan drawing and its exact revision; other rooms, furniture or house layouts are not supported."},{"key":"tools.create_solution_alternative","card_before":"Create an explicit new alternative from content changes","card":"Use when the owner wants a genuinely new Solution alternative for a scope, from scratch or based on an existing one. Gives the saved alternative; with select=true it is also selected and returns construction readiness, creation state and an edit entry."},{"key":"tools.create_work_record","card_before":"Explicitly create new work from a read scope and optional base.","card":"Use when a genuinely new Area, Task, measurement or build day is needed, optionally copied from an existing one. Gives the created record and its ref; new Tasks start todo and unassigned, new measurements unknown until evidence is supplied."},{"key":"tools.decide_project_plan","card_before":"Approve or reject one exact living Project Plan proposal. Approval changes the current plan; rejection leaves the current approved plan unchanged.","card":"Use when the owner approves or rejects a specific saved living-plan proposal, or has told you to apply that exact edit. Gives the decision: approval makes it the current plan and applies its staged Task ownership; rejection leaves the current plan unchanged."},{"key":"tools.delete_project_build_day","card_before":"Delete a build day that will not happen.","card":"Use when a planned build day will not happen. Gives the deleted day with its sign-ups and scheduled Task links removed; the Tasks themselves stay."},{"key":"tools.delete_project_task","card_before":"Delete a Task that no longer belongs to the project.","card":"Use when a Task no longer belongs to the project at all, not when it merely needs revising. Gives the deleted Task together with its checkpoints, assignments, dependencies, needs and image attachments; completed Tasks are kept as history."},{"key":"tools.delete_shopping_item","card_before":"Remove an item from the Shopping list.","card":"Use when a Shopping list item is no longer needed or was added by mistake. Gives the removed row; a linked material requirement stays and only loses its Shopping link."},{"key":"tools.derive_cad_material_requirement","card_before":"Derive a versioned blank material requirement from a saved CAD drawing or construction checkpoint.","card":"Use when a material need should be saved from a saved CAD drawing or Construction revision, for one used material definition or for its fasteners or glue. Gives a versioned requirement counted from the saved geometry and instances; Construction blank needs stay concept quantities, blocked from allocation and Shopping."},{"key":"tools.derive_construction_lists","card_before":"Derive concept part quantities, blank cut dimensions and a proposed assembly order from the exact checked construction.","card":"Use when the owner wants a parts list, cut sizes, fastener totals or an assembly order for a checked Construction. Gives a read-only concept BOM, one blank cut row per instance, joint references and the fastener schedule; an assembly order only when you name joint prerequisites."},{"key":"tools.describe_project_image","card_before":"Cache a short, unverified visual description of a viewed image.","card":"Use after you have viewed an image's pixels this turn and a short note would help pick it later. Gives a cached, unverified description of the visible content for future image selection; optional, and not project truth."},{"key":"tools.design_project_cad","card_before":"Ask the drawing team to render and independently review an exact checked construction revision, or continue its existing drawing request.","card":"Use when the owner wants a drawing of one saved, checked Construction revision, or an existing drawing request should continue or be renewed after a correction. Gives an independently reviewed render candidate that still needs save_cad_design; it cannot design a replacement assembly."},{"key":"tools.detach_project_image","card_before":"Detach an image from an Area, Task, instruction step or plan Step.","card":"Use when an image should no longer appear on a particular Area, Task, instruction step or plan Step. Gives the removed attachment; the image itself stays in the project library."},{"key":"tools.edit_construction_parts","card_before":"Change only named parts and dependencies of an exact saved construction.","card":"Use when named parts of a saved Construction change in shape, material, formula or joints, or parts are added or removed. Gives a merged new revision with everything else kept and its whole-model check; value-only changes use change_construction_parameters. Can update the selected Solution atomically."},{"key":"tools.edit_project_plan","card_before":"Prepare focused edits to the current plan while preserving unrelated Steps, criteria and Task ownership exactly.","card":"Use when the current plan needs a focused change: update, add, move or remove a Step or Completion Requirement, or move a Task, keeping everything else exact. Gives a read-only savable proposal for save_compiled_project_plan; nothing changes until it is saved and decided."},{"key":"tools.edit_project_record","card_before":"Apply requested content changes to a previously read project description or solution.","card":"Use when the project description or an existing Solution should change only where asked: text, design intent, features, choices or its early 2D model. Gives the revised record; a selected Solution advances its selection and returns a fresh edit_ref and construction readiness."},{"key":"tools.edit_project_room_layout","card_before":"Move the shared wall, place the linked furniture, or explicitly refresh sources in an existing two-room layout. Does not change the furniture construction.","card":"Use when an existing two-room layout drawing needs its shared wall moved, its furniture placed differently, or its sources refreshed. Gives a new revision of that layout drawing; the furniture construction and the real building stay unchanged."},{"key":"tools.edit_work_record","card_before":"Change only requested content on an existing work record.","card":"Use when the content of an existing Area, Task, measurement or build day, or the project's start and end dates, should change. Gives the record with only those fields set or appended, and a fresh ref; status, assignments and scheduled Tasks stay."},{"key":"tools.ensure_drawing_gap_task","card_before":"Reuse or create a Task for a canonical drawing requirement.","card":"Use when a drawing gap tied to an already shared current plan requirement needs a Task someone can do. Gives that requirement's Task, reused if it exists or created once; private-only needs stay in chat."},{"key":"tools.finalize_project_image","card_before":"Recover a previously uploaded pending image.","card":"Use when an image upload succeeded but the image stayed pending because finalization failed. Gives the same image marked ready after its storage is checked; nothing is generated or uploaded again."},{"key":"tools.generate_project_image","card_before":"Generate, save and attach a project mockup or instruction image.","card":"Use when the owner wants an illustrative mockup of a planned build, possibly in a photographed place, or an instruction image. Gives a generated image saved privately and attached to its target; it is an illustration, not measured geometry or a CAD drawing."},{"key":"tools.get_work_history","card_before":"Retrieve original tool arguments and results from this work, or browse its operation index.","card":"Use when you need the exact arguments or result of a tool call made earlier in this work, rather than running it again. Gives the original call and result pages for a call_id, or the operation index when call_id is null."},{"key":"tools.inspect_building_projection","card_before":"Inspect what mapped rooms lie vertically above or below a rectangular area in a saved multi-floor plan. Read-only; this is not a stair calculation.","card":"Use when you need to know which mapped rooms lie above or below a rectangular area in a saved multi-floor plan. Gives the intersected room footprints and known floor and slab heights, read-only; it does not calculate a stair, path or safe opening."},{"key":"tools.inspect_stair_options","card_before":"Compare straight or quarter-turn stairs with a square landing on a saved multi-floor plan. Read-only geometric study; not a rounded/winder stair generator.","card":"Use when the owner considers a stair between floors of a saved multi-floor plan and 1–4 candidates should be compared. Gives read-only treads, landing, exit, headroom and overlap conflicts per candidate; straight or quarter-turn with square landing only. save_project_stair keeps one."},{"key":"tools.link_cad_shell_steps","card_before":"Link the pieces of a shell drawing to current plan Steps in one go, or unlink them.","card":"Use when the pieces of a shell drawing should be tied to the plan Steps that build them, or untied. Gives the links, held by each piece and set in one call; the shell itself is unchanged."},{"key":"tools.link_drawing_gap","card_before":"Link a drawing gap to existing project work.","card":"Use when a drawing gap should point at a Task or Step that already exists. Gives the saved gap link, unchanged on repeat; existing links are not silently replaced, and null references keep the gap in chat."},{"key":"tools.link_project_drawing","card_before":"Link or unlink a saved drawing and a project Step without redrawing.","card":"Use when one saved drawing should be connected to, or disconnected from, the plan Step it describes. Gives the link without redrawing; one drawing can serve several Steps."},{"key":"tools.link_project_plan_evidence","card_before":"Link exact current project evidence to one Completion Requirement in the current approved living plan.","card":"Use when a project record, at its exact revision, shows why a Completion Requirement in the current approved plan is resolved, conflicted, refined or superseded. Gives the evidence link, which can satisfy or conflict that requirement; the source record is unchanged."},{"key":"tools.link_project_plan_task","card_before":"Link, move or unlink an existing Task and a stable current plan Step.","card":"Use when an existing Task should be tied to a current plan Step: assign an unowned Task, add a reference, move its primary Step, or unlink. Gives the saved association; the Task is never duplicated and its progress counts once."},{"key":"tools.manage_project_material","card_before":"Manage material stock, requirements, allocations and explicit Shopping handoff.","card":"Use when stock, material requirements, supplier products or Shopping must change: record stock, revise needs, reserve or release sheets for a saved cut plan, or publish needs or pack purchases to Shopping. Gives the saved revision; a Shopping entry is planned, not bought."},{"key":"tools.manage_task_readiness","card_before":"Manage task dependencies, tool/information needs and readiness.","card":"Use when a Task has a real dependency, a tool or information need, or is due a readiness review. Gives the recorded dependency, need or review; a new need starts unresolved and becomes ready only from evidence."},{"key":"tools.plan_cad_pieces","card_before":"Split a large build into separately designed and saved drawing pieces.","card":"Use when a larger build splits naturally into 2–12 separately saved and checked Construction pieces that each need a drawing. Gives queued drawing requests rendered one piece at a time; a queued piece is not yet a delivered drawing. For one Construction use design_project_cad."},{"key":"tools.propose_project_plan","card_before":"Create a reviewable living Project Plan proposal with dynamic Steps, Completion Requirements, responsibility and evidence selectors. It is not current until explicitly approved.","card":"Use when a living-plan proposal must be written by hand because neither compile_project_plan nor edit_project_plan can produce it. Gives a reviewable proposal with Steps, Completion Requirements and staged Task ownership; it is not current until decided."},{"key":"tools.read_building_scope","card_before":"Find the owner's buildings, their rooms and this project's Areas as server-bound choices.","card":"Use when you need to find which building the owner means, its rooms, or where this project's Areas are mapped. Gives buildings you can edit or the project links, with link kind, or rooms and Area mappings, as refs for change_building_scope."},{"key":"tools.read_cad_shell","card_before":"Read a shell drawing: pinned pieces, placements, footprints and which pieces have newer saved revisions.","card":"Use before changing a shell drawing, or when asked what it contains. Gives its pieces with pinned revisions, placements, footprints, linked Steps, summed material requirements and which pieces have newer saved revisions."},{"key":"tools.read_construction_changes","card_before":"Read saved affected-output work for an exact construction revision.","card":"Use after a Construction change, or a lost response, to see which saved outputs it affects. Gives the affected-output items for that revision with exact output revisions, completed readback and pending actions, paged; read-only. continue_construction_change processes each item."},{"key":"tools.read_construction_delivery","card_before":"Find saved outputs for one exact construction version.","card":"Use when you need to know which drawings, material requirements and cut plans already exist for one exact Construction revision. Gives an index of the latest matching revision of each output with current and archived state; reopen details through their own readers."},{"key":"tools.read_construction_draft","card_before":"List construction drafts or read one exact saved revision.","card":"Use when you need to see a Construction: list drafts, read its overview, parts, parameters, dependencies or notes, reopen a saved check, or gather a work packet before authoring or changing geometry. Gives exact revision-bound pages with coverage and next reads."},{"key":"tools.read_conversation_message","card_before":"Read an exact original message in this private conversation by its sequence.","card":"Use when you need the full original text of a message in this private conversation, by its sequence from history search or the memory index. Gives that message, paged when long; it explains intent, not current project state."},{"key":"tools.read_drawing_request_work","card_before":"Read saved drawing gaps, Task and Step links, and the request work state.","card":"Use before creating follow-up Tasks for a drawing request. Gives its stable gaps, existing Task and Step links, work state and remaining request budget."},{"key":"tools.read_drawing_requests","card_before":"Read shared minimal drawing request status without private chat.","card":"Use when you need the status of the project's drawing requests, or a request's current revision before cancelling or restoring it. Gives minimal shared status and saved Artifact references per request, without private chat or drafts."},{"key":"tools.read_material_catalog","card_before":"Read an exact material/part definition or a versioned specification profile, including dynamic fields, units and source state.","card":"Use when a material, part or profile found by search_material_catalog must be read exactly before pinning or saving. Gives that definition or profile revision with all fields, units and parameter names; it is not stock or geometry."},{"key":"tools.read_model_feedback","card_before":"Read the shown model and its scoped feedback.","card":"Use when the owner responds to a model preview shown in this turn and you need what was shown and earlier feedback. Gives the exact presentation with source freshness and the latest scoped feedback, or not_shown; no geometry is reread."},{"key":"tools.read_plan_link_context","card_before":"Read current plan Steps and Tasks as server-bound choices.","card":"Use before setting Bob focus or tying existing Tasks to plan Steps. Gives the current approved plan's focus, Steps or Tasks as server-bound refs, paged; read-only."},{"key":"tools.read_project_edit_context","card_before":"Read complete project description or solution content for a server-bound edit.","card":"Use before changing the content of the project description or an existing Solution. Gives the complete content with server-bound edit_refs for edit_project_record, including each selected Solution per scope."},{"key":"tools.read_project_orientation","card_before":"Read exact deferred Steps, completion requirements and shared facts from this project overview, with source revisions.","card":"Use when the project overview defers records you need in full, such as Steps, completion requirements or shared facts. Gives those exact records with source revisions, paged by snapshot and cursor; read every deferred requirement before judging completion."},{"key":"tools.read_project_record_section","card_before":"Read sections of an oversized plan or CAD artifact.","card":"Use when a plan or CAD record came back too large, or you need part of an exact CAD recipe or a drawing's metadata and linked Steps. Gives the selected JSON section, or its keys and array lengths to narrow further; read-only."},{"key":"tools.read_project_work","card_before":"Read task readiness, stock, material requirements, Shopping and scheduled build days.","card":"Use when you need current operational records: Task readiness and needs, stock, material requirements and allocations, cut plans, supplier products, pack purchases, Shopping or build days. Gives paged records or one exact record with source and capacity states; read-only."},{"key":"tools.read_source_findings","card_before":"Ask a small reader one concrete question about the exact text sources of the next piece of work.","card":"Use when you have one concrete question about what the next piece of work's text sources say: Solution summary, features and choices, Step requirements, Construction description and open questions. Gives a small reader's findings, each quoting its source verbatim; interpretation, not project truth."},{"key":"tools.read_task_sources","card_before":"Collect the governing sources for the next piece of work in one read.","card":"Use when starting the next piece of work and you need its governing sources together: the selected Solution's features and open choices, the Step's completion requirements and the Construction's state. Gives them with exact revisions, conflicts, coverage and reopen pointers; read-only."},{"key":"tools.record_model_feedback","card_before":"Save ordinary feedback on the shown model.","card":"Use when the owner's reply responds to the model shown in this turn. Gives the meaning of that reply saved as scoped feedback on the shown revision; a correction counts as change requested and silence is not acceptance."},{"key":"tools.restore_drawing_request","card_before":"Restore the initiating member's paused drawing from an explicit current plan Step.","card":"Use when the owner wants a paused drawing request of theirs to resume from a current approved plan Step. Gives the same request back in collecting state with that Step's requirements; continue with design_project_cad, since lost chat is not recovered."},{"key":"tools.save_building_context","card_before":"Record a narrated house as linked Building, Level, Space and element observations or proposals. This records context; it does not calculate a drawing.","card":"Use when the owner asks to save a described house: Building, levels, spaces, elements, relationships or room measurement references. Gives one atomic batch recorded as observations or proposals in the building model; linking an existing building goes through change_building_scope."},{"key":"tools.save_cad_design","card_before":"Save the exact rendered CAD candidate and its project Step link.","card":"Use after design_project_cad returns a ready, reviewed candidate. Gives the saved concept drawing Artifact with its Construction source pin and plan Step link; sources are rechecked at save."},{"key":"tools.save_catalog_definition","card_before":"Find or create a reusable project material/part definition, or revise an exact existing project definition. No new stock, drawing, Shopping purchase or global publication.","card":"Use when a material or part the project needs is not in the catalog yet, or a project definition must be revised. Gives the reused equivalent or a new or revised project definition; no stock, drawing, order or global publication."},{"key":"tools.save_compiled_project_plan","card_before":"Save the exact server-valid compilation after Bob assesses the advisory review. Bob decides; nano does not veto. Creates a proposal only, never approval.","card":"Use after compile_project_plan or edit_project_plan in this turn returned a server-valid result you accept. Gives that exact result saved as a reviewable proposal with staged Task ownership; it takes no arguments and does not approve."},{"key":"tools.save_construction_cut_plan","card_before":"Save a checked sheet-cutting layout under the existing exact blank needs.","card":"Use when a feasible sheet layout for all blank needs of the current Construction should be kept, from hypothetical formats, stock or catalog panels. Gives a saved cut plan computed and replayed by code; stock reservation and Shopping stay separate in manage_project_material."},{"key":"tools.save_construction_draft","card_before":"Save or revise a versioned construction with parts, exact materials and typed joints, without rendering.","card":"Use when a new Construction must be authored, or an existing one revised as a whole, from the selected Solution's design intent. Gives a saved revision with parts, materials and typed joints plus its whole-model check; small edits use change_construction_parameters or edit_construction_parts."},{"key":"tools.save_project_area","card_before":"Create or revise an optional Area grouping for project Steps.","card":"Use when the project needs a new optional Area grouping of Steps, or an existing Area should be revised. Gives the saved Area; it is not a physical room and moves no existing work."},{"key":"tools.save_project_build_day","card_before":"Create or revise build days with scheduled project Tasks.","card":"Use when a build day should be scheduled or revised, including which Tasks are planned for it. Gives the saved build day with its explicit Task list; RSVPs and completed work are untouched."},{"key":"tools.save_project_building_plan","card_before":"Create or revise a multi-floor coordinate study using existing Building/Level/Space identities, explicit room bounds and floor heights.","card":"Use when floors and rooms need a coordinate study: a multi-floor plan with room bounds and floor heights over existing Building, Level and Space records. Gives a saved Concept plan with all its views; unknown bounds stay null, and it is not a stair or opening."},{"key":"tools.save_project_description","card_before":"Save the requested project description while preserving unrelated information. Does not select a target, accept a Building proposal or certify a design.","card":"Use when the owner asks to change the project's description. Gives the saved description as a full replacement that keeps unrelated content; it selects no design and certifies nothing."},{"key":"tools.save_project_drawing","card_before":"Create or revise the existing rectangular, open-top storage-box drawing from four dimensions. This specific legacy tool cannot draw a bed or an arbitrary assembly.","card":"Use when the owner wants an open-top rectangular storage box drawn from width, height, depth and sheet thickness. Gives a saved 2D Concept drawing with front, plan, section and part sizes; no lid, runners or other furniture."},{"key":"tools.save_project_measurement","card_before":"Record or correct a project measurement with source and revision history. Design choices are specifications, not measurements.","card":"Use when a real measurement should be recorded, or an existing one corrected, with its source. Gives a new revision of that measurement with history kept; chosen design dimensions are specifications, not measurements."},{"key":"tools.save_project_solution","card_before":"Create or revise a visible solution with design intent, references and advised decisions.","card":"Use when a shared Solution with design intent, references and expert advice should be created or revised for its next deliverable. Gives the saved Solution revision; selecting it as the project target is a separate step."},{"key":"tools.save_project_stair","card_before":"Save or revise a straight or square-landing quarter-turn stair study linked to an exact house-plan revision. Does not support rounded/winder/spiral stairs.","card":"Use when a stair option should be kept as a study on an exact multi-floor plan, after inspecting that plan. Gives a saved or revised Concept stair linked to the plan revision; straight or square-landing quarter-turn only."},{"key":"tools.save_project_task","card_before":"Create or revise a Task in the unified plan; a Task is not a living Project Plan. Its primary Step may be directly in the Project or in an Area.","card":"Use when a new Task should be created under a plan Step, or a Task's name or instructions revised. Gives the saved todo Task with its Step ownership; people, status and readiness are set elsewhere."},{"key":"tools.search_building_knowledge","card_before":"Search curated building reference notes with source, edition and review date.","card":"Use when the work needs general building guidance, such as methods, checks or questions to settle, in Swedish or English terms. Gives matching curated reference notes with applicability, required questions, checks, limits and sources; no match means a coverage gap."},{"key":"tools.search_conversation_history","card_before":"Find relevant older messages in this private conversation using text and semantic search, with references to the originals.","card":"Use when the owner refers to something said earlier in this private conversation that you no longer have. Gives source-linked excerpts of matching older messages, or recent history for an empty query; read_conversation_message opens the originals."},{"key":"tools.search_material_catalog","card_before":"Search reusable material and part definitions by material/form categories and typed properties. Also browse available profiles/categories. This is not stock or Shopping.","card":"Use when you need a material or part definition to pin, or the catalog's categories and profiles. Gives matching definitions with exact id and revision, size, unit, aliases, household stock at home and latest store prices; it is not project stock or Shopping."},{"key":"tools.select_project_target","card_before":"Select a saved solution revision as project target.","card":"Use when a saved Solution revision should become the project's chosen design target. Gives the recorded target selection; it records intent, not measured truth or approval."},{"key":"tools.select_solution_alternative","card_before":"Select a read solution in a read scope","card":"Use when an existing Solution alternative should become the selected one for its scope. Gives the new selection, plus construction readiness and an edit entry for a construction-purpose Solution; it creates nothing."},{"key":"tools.set_project_phase","card_before":"Move the project or one Area to another lifecycle phase: concept, design, planning, build or complete.","card":"Use when the project or one Area moves to another lifecycle phase: concept, design, planning, build or complete. Gives the new phase with your reason kept in its history; completing the project needs every Area complete."},{"key":"tools.set_project_plan_focus","card_before":"Choose Bob's focus in the current plan without stopping parallel work.","card":"Use when you shift which plan Step you are concentrating on. Gives the new Bob focus; Step states, phase, readiness and parallel work are unchanged."},{"key":"tools.transition_legacy_drawing","card_before":"Prepare an exact older drawing for construction-driven correction without rewriting its history.","card":"Use when an older saved drawing without a Construction source must be corrected or redrawn. Gives a Construction the server copies from its saved geometry, or the list of missing material and joint evidence; it renders nothing."},{"key":"tools.update_project_schedule","card_before":"Set or clear the project's build window.","card":"Use when the project's build window should be set, moved or cleared. Gives the saved start and end dates, or no window when both are cleared."},{"key":"tools.update_project_task_work","card_before":"Update task status and assign project people.","card":"Use when a Task's status changes or the people assigned to it change. Gives the saved status and full assignee list; done records reported work, not verified completion of the plan."}]$phase_tools_spec$::jsonb;
 item jsonb; prior shared.ai_prompt_versions; definition jsonb; next_version integer; version_uuid uuid; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for item in select value from jsonb_array_elements(specs) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
   where p.app='bob' and p.prompt_key=item->>'key' and p.retired_at is null for update of p;
  if not found then raise exception 'phase_tools_contract_missing: %',item->>'key'; end if;
  if prior.metadata->>'phase_tools_version'='1' then continue; end if;
  definition:=prior.definition;
  if item ? 'card' then
   -- A drifted card stops the publication instead of overwriting newer text.
   if definition->>'card_description' is distinct from item->>'card_before' then raise exception 'phase_tools_card_changed: %',item->>'key'; end if;
   definition:=jsonb_set(definition,'{card_description}',item->'card');
  end if;
  if item ? 'core_tools' then
   if prior.metadata->>'write_state_version' is distinct from '1' then raise exception 'phase_tools_requires_write_state'; end if;
   if definition->'core_tools' is distinct from item->'core_tools_before' then raise exception 'phase_tools_core_tools_changed'; end if;
   definition:=jsonb_set(jsonb_set(definition,'{core_tools}',item->'core_tools'),'{phase_tools}',item->'phase_tools');
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,
    -- A card-only edit keeps the prior publication name: earlier publications use it
    -- to recognise themselves, so a replay must not mistake this version for theirs.
    (prior.metadata-'seed_version'-'source_revision')||case when item ? 'card' then jsonb_build_object('card_publication','phase-tools-v1','phase_tools_version',1)
     else jsonb_build_object('publication','phase-tools-v1','phase_tools_version',1) end,
    prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(item->>'key',version_uuid);
 end loop;
 if activation<>'{}'::jsonb then perform shared.activate_ai_catalog('bob',activation); end if;
end $phase_tools_publication$;
commit;
